use std::{fs,path::Path,collections::BTreeMap,process::Command};use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn digest(b:impl AsRef<[u8]>)->String{format!("{:x}",Sha256::digest(b.as_ref()))}
fn normalize(s:&str,base:u64,end:u64)->String{
 let s=s.trim();let (body,comment)=s.split_once('#').unwrap_or((s,""));let mut body=body.trim().to_owned();
 if let Some(start)=body.find("[rip") {if let Some(end)=body[start..].find(']'){body.replace_range(start..start+end+1,"[rip-relative]");}}
 let mnemonic=body.split_whitespace().next().unwrap_or("");
 if mnemonic.starts_with('j')||mnemonic.starts_with("call") {let rest=body[mnemonic.len()..].trim();if let Some((addr,_))=rest.split_once(' '){if let Ok(addr)=u64::from_str_radix(addr,16){let target=if (base..end).contains(&addr){format!("self+{:x}",addr-base)}else{rest.find('<').map(|i|rest[i..].to_owned()).unwrap_or_else(||"direct-target".into())};body=format!("{mnemonic} {target}");}}}
 if comment.contains('<') {let sym=&comment[comment.find('<').unwrap()..];if !body.contains('<'){body.push_str(" # ");body.push_str(sym);}}
 body.split_whitespace().collect::<Vec<_>>().join(" ")
}
fn analyze(label:&str,binary:&str,root:&Path)->Value{
 let nm=Command::new("nm").args(["-S","-n","--defined-only","-C",binary]).output().unwrap();assert!(nm.status.success());let text=String::from_utf8(nm.stdout).unwrap();
 let wanted=["zopro_core::msm_affine::grouping::scalar_groups","zopro_core::msm_affine::grouping_cost::reserve","zopro_core::msm_affine::fused_kh::feed","zopro_core::msm_affine::g2_phi::hb_raw","zopro_core::msm::g2_prefix::apply","zopro_core::msm::stream_g1_impl","zopro_core::msm::reduce_layer","zopro_bn254::inverse::inverse","<zopro_core::Key>::solve_canonical_wires"];
 let mut selected=BTreeMap::new();let mut selected_lines=Vec::new();for line in text.lines(){let f:Vec<_>=line.split_whitespace().collect();if f.len()<4{continue;}let name=f[3..].join(" ");if wanted.iter().any(|w|name.starts_with(w))&&!name.contains("closure#") {let start=u64::from_str_radix(f[0],16).unwrap();let size=u64::from_str_radix(f[1],16).unwrap();selected.insert(name,(start,size));selected_lines.push(line);}}
 fs::write(root.join(format!("{label}.symbols.txt")),selected_lines.join("\n")+"\n").unwrap();let mut out=BTreeMap::new();for(name,(start,size))in selected{let o=Command::new("objdump").args(["-d","-w","--no-show-raw-insn","-C","-Mintel",&format!("--start-address={start}"),&format!("--stop-address={}",start+size),binary]).output().unwrap();assert!(o.status.success());let disasm=String::from_utf8(o.stdout).unwrap();let mut instructions=Vec::new();let mut stack_refs=0;let mut frame=Vec::new();for line in disasm.lines(){if let Some((addr,body))=line.trim().split_once(':'){if u64::from_str_radix(addr,16).is_ok(){let body=body.trim();if body.is_empty(){continue;}if body.contains("[rsp")||body.contains("[rbp"){stack_refs+=1;}if body.starts_with("sub")&&body.contains("rsp,"){frame.push(body.to_owned());}instructions.push(normalize(body,start,start+size));}}}
  if name=="zopro_core::msm_affine::grouping::scalar_groups" {fs::write(root.join(format!("{label}.grouping.asm.txt")),&disasm).unwrap();fs::write(root.join(format!("{label}.grouping.normalized.txt")),instructions.join("\n")+"\n").unwrap();}
  out.insert(name,json!({"address":start,"size_bytes":size,"instruction_count":instructions.len(),"address_normalized_text_sha256":digest(instructions.join("\n")),"stack_reference_instructions":stack_refs,"sub_rsp_instructions":frame}));
 }
 assert!(out.contains_key("zopro_core::msm_affine::grouping::scalar_groups"));json!({"binary":binary,"binary_sha256":digest(fs::read(binary).unwrap()),"functions":out})
}
fn main(){let r=Path::new("/tmp/zopro-isolated-grouping/audit");fs::create_dir_all(r).unwrap();let args:Vec<_>=std::env::args().skip(1).collect();let mut results=BTreeMap::new();for pair in args.chunks(2){assert_eq!(pair.len(),2);results.insert(pair[0].clone(),analyze(&pair[0],&pair[1],r));}fs::write(r.join("results.json"),serde_json::to_vec_pretty(&results).unwrap()).unwrap();for(label,r)in results{let f=&r["functions"]["zopro_core::msm_affine::grouping::scalar_groups"];println!("{label}:{}bytes,{}instructions,{}stackrefs",f["size_bytes"],f["instruction_count"],f["stack_reference_instructions"]);}}
#[cfg(test)]mod tests{use super::*;#[test]fn internal_branches_keep_relative_offset(){assert_eq!(normalize("jne 120 <f+0x20>",0x100,0x200),normalize("jne 320 <f+0x20>",0x300,0x400));assert_ne!(normalize("jne 120 <f+0x20>",0x100,0x200),normalize("jne 330 <f+0x30>",0x300,0x400));}#[test]fn stack_offsets_and_registers_are_preserved(){assert_ne!(normalize("mov rax,QWORD PTR [rsp+0x20]",0,10),normalize("mov rax,QWORD PTR [rsp+0x28]",0,10));assert_ne!(normalize("mov rax,rbx",0,10),normalize("mov rax,rcx",0,10));}#[test]fn rip_targets_keep_symbol(){assert_eq!(normalize("lea rax,[rip+0x123] # 300 <foo>",0,10),normalize("lea rax,[rip-0x300] # 100 <foo>",0,10));assert_ne!(normalize("lea rax,[rip+0x123] # 300 <foo>",0,10),normalize("lea rax,[rip+0x123] # 300 <bar>",0,10));}}
